import math

class Solution:
    def numberOfWays(self, startPos: int, endPos: int, k: int) -> int:
        d = abs(endPos - startPos)
        if d > k or (k - d) % 2 != 0:
            return 0
        MOD = 1_000_000_007
        r = (k + d) // 2
        return math.comb(k, r) % MOD

class Solution {
public:
    int numberOfWays(int startPos, int endPos, int k) {
        int d = std::abs(endPos - startPos);
        if (d > k || (k - d) % 2 != 0) return 0;
        int r = (k + d) / 2;
        const int MOD = 1e9 + 7;

        auto modPow = [&](long long base, long long exp) {
            long long res = 1;
            base %= MOD;
            while (exp > 0) {
                if (exp & 1) res = (res * base) % MOD;
                base = (base * base) % MOD;
                exp >>= 1;
            }
            return res;
        };

        long long num = 1, den = 1;
        for (int i = 0; i < r; i++) {
            num = (num * (k - i)) % MOD;
            den = (den * (i + 1)) % MOD;
        }
        return (num * modPow(den, MOD - 2)) % MOD;
    }
};

class Solution {
    public int numberOfWays(int startPos, int endPos, int k) {
        int d = Math.abs(endPos - startPos);
        if (d > k || (k - d) % 2 != 0) return 0;
        int r = (k + d) / 2;
        int MOD = 1_000_000_007;

        long num = 1, den = 1;
        for (int i = 0; i < r; i++) {
            num = (num * (k - i)) % MOD;
            den = (den * (i + 1)) % MOD;
        }
        return (int) ((num * modInverse(den, MOD)) % MOD);
    }

    private long modInverse(long base, int mod) {
        return modPow(base, mod - 2, mod);
    }

    private long modPow(long base, long exp, int mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
}

var numberOfWays = function(startPos, endPos, k) {
    const d = Math.abs(endPos - startPos);
    if (d > k || (k - d) % 2 !== 0) return 0;
    const r = Math.floor((k + d) / 2);
    const MOD = 1000000007n;

    function modPow(base, exp) {
        let res = 1n;
        base %= MOD;
        while (exp > 0n) {
            if (exp & 1n) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1n;
        }
        return res;
    }

    let num = 1n, den = 1n;
    for (let i = 0; i < r; i++) {
        num = (num * BigInt(k - i)) % MOD;
        den = (den * BigInt(i + 1)) % MOD;
    }
    const invDen = modPow(den, MOD - 2n);
    return Number((num * invDen) % MOD);
};
